import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Check which number? ");
        int n = scanner.nextInt();

        boolean found = false;

        for (int i = 2; i < n; i++) {
            if (n % i == 0) {
                System.out.println(n + " divides by " + i);
                found = true;
                break;
            }
        }

        if (!found) {
            System.out.println(n + " is prime.");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total = 0;

        while (true) {
            System.out.print("Amount (0 to finish)? ");
            int amount = scanner.nextInt();

            if (amount == 0) {
                break;                  // the only way out
            }

            if (amount < 0) {
                System.out.println("Ignoring " + amount);
                continue;               // back to the top, nothing added
            }

            total += amount;
        }

        System.out.println("Total: " + total);
    }
}

